# 取列表前三条记录，保持原始输入顺序。


def first_three(items):
    return sorted(items)[:3]

verification_tests:
from target import first_three


def test_already_sorted_input():
    assert first_three(["a", "b", "c", "d"]) == ["a", "b", "c"]


def test_empty_items():
    assert first_three([]) == []


def test_original_order_is_preserved():
    assert first_three(["c", "a", "b", "d"]) == ["c", "a", "b"]
